import type {Validation} from '../linter-util'
import type {Suggestion} from './autocomplete-types'

export type YamlFile = unknown

export async function ruleValues(rule: Rule, yaml: YamlFile, path: string[]): Promise<string[]> {
  if (!rule.values) throw new Error('Cannot get values of rule because `values` is not defined')
  return typeof rule.values === 'function' ? await rule.values(yaml, path) : rule.values
}

// Types for the rule system
export interface Rule {
  description?: string // description for this key to be shown in autocomplete
  single?: string[] // can be a single value? Of which type? → 'string' | 'number' | 'boolean'
  required?: boolean // is it required?
  values?: string[] | ((yaml: unknown, path: string[]) => Promise<string[]>)
  multipleValues?: boolean // can be an array of things in "values"
  caseInsensitive?: boolean // the values are case insensitive?
  nullable?: boolean // can be null? We could've used `single: ['null']` but that'd change some behaviors
  // can be an object? Which rules its properties have?
  rules?: Rules // if the value expected is another object, define it using rules
  map?: Rule // can be an object with user-defined keys? What rule applies to the values?
  keyPlaceholder?: string // placeholder when using smart indentation
  keyPlaceholderHelp?: string // help to show when selecting the placeholder
  items?: Rule // can be an array? What are the rules for its elements?
  maxLength?: number // maximum number of elements if object is an array
  validateKey?: (yaml: YamlFile, path: string[]) => Promise<Validation | undefined>
  validateValue?: (yaml: YamlFile, path: string[], value: unknown) => Promise<Validation | undefined>
  sortSuggestions?: boolean // default true, should we sort suggestions by similarity?
}

export type suggestionsForExpressionSignature = (
  yaml: YamlFile,
  path: string[],
  lastValue: string,
) => Promise<Suggestion[] | null>

export type processExpressionSignature = (
  yamlContent: YamlFile,
  path: string[],
  expression: string,
  rule: Rule,
) => Promise<Validation | undefined>

export type getYamlRootRuleSignature = (yaml: YamlFile) => RootRule

export interface RootRule extends Rule {
  processExpression?: processExpressionSignature
  suggestionsForExpression?: suggestionsForExpressionSignature
}

export interface Rules {
  [index: string]: Rule
}

export function ruleForPath(path: string[], fullRootRule: RootRule): Rule | null {
  let rule = fullRootRule
  for (const key of path) {
    if (Number.isInteger(+key)) {
      if (!rule.items) return null
      rule = rule.items
    } else if (rule.map) {
      rule = rule.map
    } else if (rule.rules && rule.rules[key]) {
      rule = rule.rules[key]!
    } else {
      return null
    }
  }
  return rule
}
