import {
  type Rule,
  type YamlFile,
  type getYamlRootRuleSignature,
  type processExpressionSignature,
  ruleValues,
} from './rule-util'
import {codeTag, containsExpression, joinCodeTags, sortBySimilarity} from './utils'
import type {TemplateResult} from 'lit-html'
import {html} from 'lit-html'
import yaml from 'js-yaml'
import type {LintMessage, PathInfo, TokenInfo, Validation} from '../linter-util'

type Paths = {[key: string]: PathInfo}

function isObject(value: unknown): boolean {
  return typeof value === 'object' && value !== null
}

/*
 * If we are unable to calculate the position of a key or value, we highligh the whole line.
 * This function returns a TokenInfo object with the content of the whole function without
 * the first whitespaces
 */
function lineInfo(lineNumber: number, line: string): TokenInfo {
  const indentation = (line.match(/^\s*/) || [''])[0]
  return {
    from: {line: lineNumber, ch: indentation.length},
    to: {line: lineNumber, ch: line.length},
  }
}

/*
 * Calculates the location of a key in a line
 */
function keyInfo(lineNumber: number, line: string, key: string): TokenInfo {
  const ch = line.indexOf(key)
  if (ch === -1) return lineInfo(lineNumber, line)
  return {
    from: {line: lineNumber, ch},
    to: {line: lineNumber, ch: ch + key.length},
  }
}

/*
 * Calculates the location of a value in a line
 */
function valueInfo(lineNumber: number, line: string, value: unknown): TokenInfo {
  if (isObject(value)) return lineInfo(lineNumber, line)
  const asString = String(value)
  const ch = line.lastIndexOf(asString)
  if (ch === -1) return lineInfo(lineNumber, line)
  return {
    from: {line: lineNumber, ch},
    to: {line: lineNumber, ch: ch + asString.length},
  }
}

function buildKeyMessage(paths: Paths, path: string[], validation: Validation): LintMessage {
  const fullPath = path.join('.')
  const pathInfo = paths[fullPath]!
  const {message, fixes, severity} = validation
  return {message, fixes, severity, from: pathInfo.key.from, to: pathInfo.key.to}
}

function buildValueMessage(paths: Paths, path: string[], validation: Validation): LintMessage {
  const fullPath = path.join('.')
  const pathInfo = paths[fullPath]!
  const {message, fixes, severity} = validation
  return {message, fixes, severity, from: pathInfo.value.from, to: pathInfo.value.to}
}

/*
 * Calculates the repeated values of an array of strings
 */
function repeatedValues(array: string[]): string[] {
  const set = new Set()
  const repeated = new Set<string>()
  for (const value of array) {
    if (set.has(value)) repeated.add(value)
    set.add(value)
  }
  return [...repeated]
}

export function unexpectedTypeMessage(expected: string[], found: string | TemplateResult): Validation {
  const part =
    expected.length === 1
      ? html` ${codeTag(expected[0]!)} was expected `
      : html` one of ${joinCodeTags(expected)} were expected `
  return {
    message: html` Invalid type found: ${part} but ${found} was found `,
    severity: 'error',
  }
}

interface ValidateParams {
  yamlContent: YamlFile
  paths: Paths
  path: string[]
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  object: any
  rule?: Rule
  messages: LintMessage[]
  processExpression?: processExpressionSignature
}

async function validate({yamlContent, paths, path, object, rule, messages, processExpression}: ValidateParams) {
  if (object === undefined) return
  if (rule === undefined) return

  if (rule.validateKey) {
    const validation = await rule.validateKey(yamlContent, path)
    if (validation) {
      messages.push(buildKeyMessage(paths, path, validation))
      if (validation.severity === 'error') return // Stop validation of nested values
    }
  }

  if (object === null) {
    if (rule.nullable === true) return
    messages.push(
      buildValueMessage(paths, path, {
        message: html` This value cannot be null `,
        severity: 'error',
      }),
    )
  } else if (typeof object === 'object') {
    if (Array.isArray(object)) {
      if (rule.maxLength && object.length > rule.maxLength) {
        messages.push(
          buildValueMessage(paths, path, {
            message: html` Maximum of ${rule.maxLength.toString()} elements allowed `,
            severity: 'error',
          }),
        )
      }

      if (rule.values) {
        if (rule.multipleValues !== true) {
          messages.push(
            buildValueMessage(paths, path, {
              message: html` Only a single value is allowed here `,
              severity: 'error',
            }),
          )
          return
        }
        const values = await ruleValues(rule, yamlContent, path)
        const unknown = object.map(String).filter(value => !values.includes(value))
        const known = object.map(String).filter(value => values.includes(value))
        const repeated = repeatedValues(known)
        if (repeated.length > 0 || unknown.length > 0) {
          const message = html`
            ${repeated.length > 0 ? html` Repeated values: ${joinCodeTags(repeated)} ` : ''}
            ${repeated.length > 0 && unknown.length > 0 ? html` <br /> ` : ''}
            ${unknown.length > 0 ? html` Invalid values: ${joinCodeTags(unknown)} ` : ''}
          `
          messages.push(buildValueMessage(paths, path, {message, severity: 'error'}))
        }
      } else if (rule.items) {
        for (const index in object) {
          await validate({
            yamlContent,
            paths,
            path: [...path, index],
            object: object[index],
            rule: rule.items,
            messages,
            processExpression,
          })
        }
      } else if (rule.single || rule.map || rule.rules) {
        const expected = rule.single || []
        if (rule.map) expected.push('map')
        if (rule.rules) expected.push('object')
        messages.push(buildValueMessage(paths, path, unexpectedTypeMessage(expected, 'an array')))
      }
    } else {
      if (rule.map) {
        for (const index in object) {
          await validate({
            yamlContent,
            paths,
            path: [...path, index],
            object: object[index],
            rule: rule.map,
            messages,
            processExpression,
          })
        }
      } else if (rule.rules) {
        const {rules} = rule
        for (const ruleKey in rules) {
          if (object[ruleKey] !== undefined) {
            // Validate existing rule/key
            await validate({
              yamlContent,
              paths,
              path: [...path, ruleKey],
              object: object[ruleKey],
              rule: rules[ruleKey],
              messages,
              processExpression,
            })
          } else if (rules[ruleKey]!.required === true) {
            // Look for missing required properties
            const keyMessage = path.length === 0 ? 'root key' : 'key'
            messages.push(
              buildKeyMessage(paths, path, {
                message: html` Missing required ${keyMessage} ${codeTag(ruleKey)} `,
                severity: 'error',
              }),
            )
          }
        }
        // Look for unknown keys
        for (const index in object) {
          if (!rule.rules[index]) {
            const expected = Object.keys(rule.rules).filter(key => object[key] === undefined)
            const message = html` Unknown key ${codeTag(index)} `
            const fixes = rule.sortSuggestions === false ? expected : sortBySimilarity(expected, index)
            messages.push(buildKeyMessage(paths, [...path, index], {message, fixes, severity: 'error'}))
          }
        }
      } else if (rule.single || rule.items) {
        const expected = rule.single || []
        if (rule.values || rule.items) expected.push('array')
        messages.push(
          buildValueMessage(
            paths,
            path,
            unexpectedTypeMessage(expected, object instanceof Date ? 'a date' : 'an object'),
          ),
        )
      }
    }
  } else {
    const str = String(object)
    if (containsExpression(str) && processExpression) {
      const validation = await processExpression(yamlContent, path, str, rule)
      if (validation) messages.push(buildValueMessage(paths, path, validation))
      return
    }

    if (rule.validateValue) {
      const validation = await rule.validateValue(yamlContent, path, object)
      if (validation) {
        messages.push(buildValueMessage(paths, path, validation))
        if (validation.severity === 'error') return
      }
    }
    if (rule.single) {
      const {single: types} = rule
      const objectType = typeof object

      if (!types.includes(objectType)) {
        messages.push(buildValueMessage(paths, path, unexpectedTypeMessage(types, codeTag(objectType))))
      }
    } else if (rule.values) {
      const values = await ruleValues(rule, yamlContent, path)
      // If the rule is caseInsensitive we assume the values in the rule are already case insensitive
      const includesValue = values.includes(rule.caseInsensitive ? str.toLowerCase() : str)
      if (!includesValue) {
        const fixes = rule.sortSuggestions === false ? values : sortBySimilarity(values, String(object))
        messages.push(
          buildValueMessage(paths, path, {
            message: html` Invalid value: ${codeTag(str)} `,
            fixes,
            severity: 'error',
          }),
        )
      }
    } else if (rule.map || rule.rules || rule.items) {
      const objectType = object === null ? 'null' : typeof object
      const expected = []
      if (rule.map || rule.rules) expected.push('object')
      if (rule.items) expected.push('array')
      messages.push(buildValueMessage(paths, path, unexpectedTypeMessage(expected, codeTag(objectType))))
    }
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function findNewPaths(paths: Paths, lines: string[], value: any, path: string[], lineNumber: number) {
  if (value === undefined) return
  const fullPath = path.join('.')
  if (fullPath && !paths[fullPath]) {
    const line = lines[lineNumber]!
    const lastKey = path[path.length - 1]!
    paths[fullPath] = {
      key: keyInfo(lineNumber, line, lastKey),
      value: valueInfo(lineNumber, line, value),
    }
  }
  if (typeof value !== 'object') return
  for (const key in value) {
    if (!value.hasOwnProperty(key)) continue
    findNewPaths(paths, lines, value[key], [...path, key], lineNumber)
  }
}

export default async function lint(text: string, getRootRule: getYamlRootRuleSignature): Promise<LintMessage[]> {
  const paths: Paths = {}
  const lines = text.split('\n')
  try {
    if (lines.length > 0) {
      // This is needed to show error messages for the root object.
      // Only case right now: missing root keys, such as `on`
      const info = {
        from: {line: 0, ch: 0},
        to: {line: lines.length - 1, ch: lines[lines.length - 1]!.length},
      }
      paths[''] = {
        key: info,
        value: info,
      }
    }

    // The parser does not return any information of the position of the data in the original text.
    // So we parse the text N times: first including the first line, then including the first two lines, and so on.
    // In each iteration we find new paths, we know that they are in the latest line being parsed.
    let yamlObject = null
    for (let i = 0; i < lines.length; i++) {
      const partial = lines.slice(0, i + 1).join('\n')
      yamlObject = yaml.load(partial)

      findNewPaths(paths, lines, yamlObject, [], i)
    }

    const messages: LintMessage[] = []
    const rootRule = getRootRule(yamlObject)
    await validate({
      yamlContent: yamlObject,
      paths,
      path: [],
      object: yamlObject,
      rule: rootRule,
      messages,
      processExpression: rootRule.processExpression,
    })

    return messages
  } catch (err) {
    // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
    const {mark} = err
    if (!mark) return [] // Unknown error
    const {line: lineIndex, column} = mark
    // Sometimes js-yaml reports an invalid line number. E.g. reports 1 when the document only has one line
    const line =
      // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
      lineIndex >= lines.length || err.reason.match(/end of the stream within a flow collection/)
        ? lineIndex - 1
        : lineIndex
    const ch = column >= lines[line]!.length ? 0 : column
    return [
      {
        // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
        message: html` ${err.reason} `,
        severity: 'error',
        from: {line, ch},
        to: {line, ch: lines[line]!.length},
      },
    ]
  }
}
